def route(items,times):
    return '<div class="route">'+''.join(cue(t,f'<span class="stepnum">{i+1}</span><h2>{a}</h2><p>{b}</p>','route-item') for i,((a,b),t) in enumerate(zip(items,times)))+'</div>'
def smalllist(items,times):
    return '<div class="catalog">'+''.join(cue(t,f'<span class="index">{num:02d}</span><strong>{tx}</strong>','catalog-row') for (num,tx),t in zip(items,times))+'</div>'

