start=0
sections=[]; timeline=[]
for i,(s,(title,kicker,body)) in enumerate(zip(scenes,content)):
    duration=math.ceil((s['duration']+.8)*30)/30
    s.update(start=round(start,6),end=round(start+duration,6),clip_duration=duration,audio_start=round(start+.3,6),title=title)
    sections.append(f'<section id="{s["id"]}" class="clip" data-start="{start:.6f}" data-duration="{duration:.6f}" data-track-index="1"><div class="inner"><header class="header"><div class="eyebrow">{kicker}</div><h1>{title}</h1></header><div class="body">{body}</div></div></section>')
    sections.append(f'<audio id="voice-{s["id"]}" src="{s["src"]}" data-start="{start+.3:.6f}" data-duration="{s["duration"]}" data-track-index="2"></audio>')
    start+=duration
total=round(start,6)
css+=' .quote-mark{display:none}'
script='''const tl=gsap.timeline({paused:true});
document.querySelectorAll('section.clip').forEach(scene=>{
const s=Number(scene.dataset.start),d=Number(scene.dataset.duration);
tl.fromTo(scene.querySelector('.header'),{opacity:0,y:14},{opacity:1,y:0,duration:.48,ease:'power2.out',immediateRender:false},s);
scene.querySelectorAll('.cue').forEach(el=>{const c=Number(el.dataset.cue);tl.fromTo(el,{opacity:0,y:18},{opacity:1,y:0,duration:.5,ease:'power2.out',immediateRender:false},s+.3+c);});
scene.querySelectorAll('.draw').forEach(el=>{const len=el.getTotalLength();tl.fromTo(el,{strokeDasharray:len,strokeDashoffset:len},{strokeDashoffset:0,duration:1.6,ease:'power2.inOut',immediateRender:false},s+.8);});
scene.querySelectorAll('.car').forEach(el=>tl.fromTo(el,{x:-25},{x:0,duration:1.2,ease:'power2.out',immediateRender:false},s+.4));
scene.querySelectorAll('.horizontal-link').forEach(el=>tl.fromTo(el,{scaleX:0,transformOrigin:'0% 50%'},{scaleX:1,duration:1.1,ease:'power2.inOut',immediateRender:false},s+4.4));
scene.querySelectorAll('.catalog-row').forEach(el=>{const c=Number(el.dataset.cue);tl.fromTo(el,{backgroundColor:'#d0e3de'},{backgroundColor:'#efeae1',duration:2.8,immediateRender:false},s+.9+c);});
scene.querySelectorAll('.pen').forEach(el=>tl.fromTo(el,{rotation:-9,transformOrigin:'50% 100%'},{rotation:0,duration:.7,repeat:3,yoyo:true,ease:'sine.inOut',immediateRender:false},s+2));
});
window.__timelines=window.__timelines||{};window.__timelines.root=tl;
'''
doc=f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>商业车险产品地图</title><style>{css}</style></head><body><div id="root" data-composition-id="root" data-width="1920" data-height="1080" data-duration="{total}" data-fps="30">'+''.join(sections)+'</div><script src="assets/gsap.min.js"></script><script>'+script+'</script></body></html>'
(P/'index.html').write_text(doc,encoding='utf-8')
(P/'timeline.json').write_text(json.dumps({'duration':total,'fps':30,'scenes':scenes},ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'scenes':len(scenes),'duration':total,'snapshot_times':[round(s['end']-1,2) for s in scenes]},ensure_ascii=False))
